const request = $('Extract Authenticated Request').first().json;
const source = request.body ?? {};
const authResponse = $('Verify Supabase Session').first().json;
const authUser = authResponse.body ?? authResponse;
const clean = (value, max) => String(value ?? '').trim().slice(0, max);

const conversationId = clean(source.conversation_id, 100);
const email = clean(authUser.email, 254).toLowerCase();
const message = clean(source.message, 4000);
const channel = clean(source.channel || 'web_chat', 32);
const authUserId = clean(authUser.id, 100);

if (!authUserId || !email) {
  throw new Error('Authenticated Supabase user is missing an id or email');
}
if (!/^[A-Za-z0-9_-]{8,100}$/.test(conversationId)) {
  throw new Error('conversation_id must contain 8-100 letters, numbers, hyphens, or underscores');
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('Authenticated email is invalid');
}
if (message.length < 2) {
  throw new Error('message must contain at least 2 characters');
}

return { json: {
  conversation_id: conversationId,
  auth_user_id: authUserId,
  email,
  message,
  channel,
  received_at: new Date().toISOString()
} };

