const raw = $json.output ?? $json;
let decision = raw;

if (typeof raw === 'string') {
  try {
    decision = JSON.parse(raw);
  } catch {
    throw new Error('Agent output was not valid JSON');
  }
}

if (!decision || typeof decision !== 'object') {
  throw new Error('Agent output is missing');
}
if (typeof decision.ready_for_ticket !== 'boolean') {
  throw new Error('ready_for_ticket must be boolean');
}

const input = $('Prepare Verified Request').first().json;
const customerResult = $('Get Verified Customer').first().json;
const clean = (value, max = 5000) => String(value ?? '').trim().slice(0, max);

const categories = ['Subscription','Billing','Refund','Account Access','Technical Support','Cancellation','Security','General Question','Other'];
const severities = ['Low','Medium','High','Critical'];
const statuses = ['Waiting for Customer','Investigating','Waiting for Approval','Completed','Failed','Escalated'];
const resolutionTypes = ['AI Resolved','Human Resolved','AI + Human','Unresolved'];
const escalationReasons = ['','technical_complexity','customer_request','policy_requirement','ai_limitation'];

const normalized = {
  ready_for_ticket: decision.ready_for_ticket,
  reply: clean(decision.reply, 2000),
  missing_information: Array.isArray(decision.missing_information)
    ? decision.missing_information.map(value => clean(value, 200)).filter(Boolean).slice(0, 5)
    : [],
  issue_category: clean(decision.issue_category, 64),
  issue_severity: clean(decision.issue_severity, 16),
  ai_handling_status: clean(decision.ai_handling_status, 64),
  requires_human_approval: decision.requires_human_approval === true,
  escalation_reason: clean(decision.escalation_reason, 64),
  resolution_type: clean(decision.resolution_type, 32) || 'Unresolved',
  subject: clean(decision.subject, 200),
  description: clean(decision.description, 5000),
  resolution_summary: clean(decision.resolution_summary, 2000),
  policy_evidence: Array.isArray(decision.policy_evidence)
    ? decision.policy_evidence.slice(0, 5).map(item => ({
        document_code: clean(item?.document_code, 64),
        section_title: clean(item?.section_title, 200)
      })).filter(item => item.document_code && item.section_title)
    : []
};

if (!normalized.reply) throw new Error('Agent reply is required');
if (!statuses.includes(normalized.ai_handling_status)) throw new Error('Invalid AI handling status');
if (!resolutionTypes.includes(normalized.resolution_type)) throw new Error('Invalid resolution type');
if (!escalationReasons.includes(normalized.escalation_reason)) throw new Error('Invalid escalation reason');

if (!normalized.ready_for_ticket) {
  normalized.ai_handling_status = 'Waiting for Customer';
  normalized.requires_human_approval = false;
  normalized.escalation_reason = '';
  normalized.resolution_type = 'Unresolved';
}

if (normalized.ready_for_ticket) {
  if (!categories.includes(normalized.issue_category)) throw new Error('Ticket-ready output needs a valid issue category');
  if (!severities.includes(normalized.issue_severity)) throw new Error('Ticket-ready output needs a valid issue severity');
  if (normalized.issue_category === 'Refund' && ['Low', 'Medium'].includes(normalized.issue_severity)) {
    normalized.issue_severity = 'High';
  }
  if (normalized.subject.length < 5) throw new Error('Ticket-ready output needs a subject');
  if (!normalized.description) throw new Error('Ticket-ready output needs a description');
  if (normalized.ai_handling_status === 'Waiting for Customer') throw new Error('Ticket-ready output cannot wait for customer');
  if (['Waiting for Approval','Escalated','Failed'].includes(normalized.ai_handling_status) && !normalized.escalation_reason) {
    throw new Error('Human Review output needs an escalation reason');
  }
  if (normalized.ai_handling_status === 'Waiting for Approval') {
    normalized.requires_human_approval = true;
  }
  if (normalized.ai_handling_status === 'Completed') {
    if (normalized.resolution_type !== 'AI Resolved') throw new Error('Completed AI case must use AI Resolved');
    if (!normalized.resolution_summary) throw new Error('Completed case needs a resolution summary');
  } else {
    normalized.resolution_type = 'Unresolved';
    normalized.resolution_summary = '';
  }
}

return { json: {
  ...input,
  customer: customerResult.customer,
  hubspot_contact_id: customerResult.hubspot?.contact_id ?? null,
  ready_for_ticket: normalized.ready_for_ticket,
  decision: normalized
} };

