const input = $('Validate Input').first().json;
const lookup = $json;
const customer = lookup.customer;

if (!customer?.customer_id) {
  throw new Error('Verified customer record is missing customer_id');
}

const customerId = String(customer.customer_id).trim().toUpperCase();
const conversationKey = input.conversation_id
  .replace(/[^A-Za-z0-9_-]/g, '-')
  .toUpperCase()
  .slice(0, 40);
const requestId = `REQ-${customerId}-${conversationKey}`.slice(0, 64);

return { json: {
  ...input,
  customer_id: customerId,
  request_id: requestId,
  customer,
  hubspot: lookup.hubspot,
  data_consistency: lookup.data_consistency,
  mismatched_fields: lookup.mismatched_fields
} };
